    			ORDER BY A.UPDT_DT DESC
			) AA
			LIMIT #{limitStart},#{limitEnd}

mapper.select:
SELECT A.BBS_SEQ , A.BBS_SE_CODE_L , A.BBS_SE_CODE_M , C.CODE_NM AS BBS_SE_NM , A.SJ , A.CN , A.ATCH_DOC_ID , A.ATCH_YN , A.REGISTER_NO , B.USER_NM AS REGISTER_NM , B.USER_ID AS REGISTER_ID ,DATE_FORMAT(A.REGIST_DT, '%Y.%m.%d') AS REGIST_DT FROM tb_board A INNER JOIN op_user B ON A.REGISTER_NO = B.USER_NO LEFT JOIN op_code C ON A.BBS_SE_CODE_L=C.GROUP_ID AND A.BBS_SE_CODE_M = C.CODE WHERE A.DELETE_YN = 'N'
AND A.BBS_SE_CODE_M = #{sch_bbs_se_code}
ORDER BY A.UPDT_DT DESC LIMIT 0,5

mapper.insert:
/*  mgt.mboard.insertBoard */
INSERT INTO tb_board (
    BBS_SEQ
	,BBS_SE_CODE_L
	,BBS_SE_CODE_M
	, SJ
	, CN
	, ATCH_DOC_ID
	, ATCH_YN
	, HIT_CNT
	, DELETE_YN
	, REGISTER_NO
	, REGIST_DT
	, UPDUSR_NO
	, UPDT_DT
) values (
	(select * from (select ifnull(max(bbs_seq),0)+1 from tb_board) next)
	,#{bbs_se_code_l}
	,#{bbs_se_code_m}
	,#{sj}
	,#{cn}
	,#{atch_doc_id}


			,#{atch_yn}


			,'Y'


	, 0
	,'N'
	,#{ss_user_no}
	, CURRENT_TIMESTAMP
	,#{ss_user_no}
	, CURRENT_TIMESTAMP
)

mapper.update:
/*  mgt.mboard.updateBoard */
UPDATE tb_board
SET SJ = #{sj}
	, CN = #{cn}

		, ATCH_DOC_ID = #{atch_doc_id}

			, ATCH_YN = #{atch_yn}


	, UPDUSR_NO = #{ss_user_no}
	, UPDT_DT = CURRENT_TIMESTAMP
WHERE BBS_SEQ = #{bbs_seq}

/* mgt.mboard.deleteBoard */
UPDATE tb_board
SET DELETE_YN = 'Y'
WHERE BBS_SEQ = #{bbs_seq}

