/* admin.mgt.board.insertFile */
INSERT INTO tb_file (
	DOC_ID, FILE_ID, FILE_NM, FILE_EXTSN_NM, FILE_SIZE, 
	FILE_PARTN_COURS, FILE_ABSLT_COURS, CNTNTS_TY, SORT_ORDR, 
	REGISTER_NO, REGIST_DT
) VALUES (
	#{doc_id}, #{file_id}, #{file_nm}, #{file_ext_nm}, #{file_size},
	#{file_rltv_path}, #{file_aslt_path}, #{content_type}, 0,
	#{ss_user_id}, CURRENT_TIMESTAMP
)

mapper.select:
/* admin.mgt.board.selectFileList */
SELECT FILE_SEQ, DOC_ID, FILE_ID, FILE_NM, FILE_EXTSN_NM, 
       FILE_SIZE, FILE_PARTN_COURS, FILE_ABSLT_COURS, CNTNTS_TY, SORT_ORDR
FROM tb_file
WHERE DOC_ID = #{atch_doc_id}
ORDER BY SORT_ORDR ASC

/* admin.mgt.board.selectFile */
SELECT FILE_SEQ, DOC_ID, FILE_ID, FILE_NM, FILE_EXTSN_NM, 
       FILE_SIZE, FILE_PARTN_COURS, FILE_ABSLT_COURS, CNTNTS_TY
FROM tb_file
WHERE FILE_ID = #{file_id}
